actor ImageCache {
    private var decoded: [Key: Image] = [:]

    func image(for key: Key) async throws -> Image {
        if let hit = decoded[key] { return hit }        // cheap path
        let img = try await decode(key)                 // once per key
        decoded[key] = img
        return img
    }
}
